// Validate input (P2: orderId mandatory UUID v4), normalize customerId + nome, compute alcohol grams, structured items_json, and Italian TTS speech
const input = $input.first()?.json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;
const validationErrors = [];

const toText = (value, fallback = '') => {
  if (value === null || value === undefined) return fallback;
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'number' || typeof value === 'boolean') return String(value).trim();
  return fallback;
};

const normalizeKey = (value) =>
  toText(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

// 1. Validate mandatory orderId (UUID v4 required for reliable deduplication)
const incomingOrderId = toText(body.orderId ?? body.order_id);
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!incomingOrderId) {
  validationErrors.push('Missing mandatory orderId: a valid UUID v4 is required for idempotent deduplication.');
} else if (!uuidRegex.test(incomingOrderId)) {
  validationErrors.push('Invalid orderId: must be a valid UUID v4.');
}
const orderId = uuidRegex.test(incomingOrderId) ? incomingOrderId.toLowerCase() : 'invalid-order-id';
const claimSid = 'menu:order:' + orderId;
const ttsIdempotencyKey = 'menu:tts:' + orderId;

// 2. Validate customer identification (customerId required or derived deterministically)
const rawCustomerId = toText(body.customerId ?? body.customer_id ?? body.userId ?? body.user_id ?? body.clientId);
const rawName = toText(body.nome ?? body.name ?? body.person ?? body.cliente);

if (!rawCustomerId && !rawName) {
  validationErrors.push('Missing customer identification: provide customerId (and optionally nome).');
}

const titleName = (value) => {
  const s = toText(value);
  if (!s) return 'Anonimo';
  return s.split(/\s+/).map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
};

const nome = titleName(rawName || rawCustomerId);
const customerId = rawCustomerId
  ? rawCustomerId.toLowerCase().replace(/[^a-z0-9:_-]+/g, '_')
  : ('cust:' + (normalizeKey(rawName).replace(/\s+/g, '_') || 'anonymous'));

// Optional physiological parameters for Widmark BAC estimate
const pesoKg = Math.min(200, Math.max(40, Number(body.pesoKg ?? body.weightKg ?? 70) || 70));
const widmarkR = Number(body.widmarkR ?? (body.sesso === 'F' ? 0.55 : 0.68)) || 0.68;

// 3. Timezone-aware date & time (Europe/Rome)
const now = new Date();
const today = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Rome' }).format(now);
const defaultOrario = new Intl.DateTimeFormat('it-IT', {
  timeZone: 'Europe/Rome',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
}).format(now);
const orario = toText(body.orario || body.time) || defaultOrario;

// 4. Validate order items & quantities
const rawOrderInput = body.ordine ?? body.order ?? body.items;
let rawItems = [];
if (Array.isArray(rawOrderInput)) {
  rawItems = rawOrderInput;
} else if (rawOrderInput && typeof rawOrderInput === 'object') {
  rawItems = Object.values(rawOrderInput);
} else if (typeof rawOrderInput === 'string' && rawOrderInput.trim()) {
  rawItems = rawOrderInput.split(',').map(x => ({ nome: x.trim(), quantita: 1 })).filter(x => x.nome);
}

if (!Array.isArray(rawItems) || rawItems.length === 0) {
  validationErrors.push('Order cannot be empty: provide at least one item in ordine.');
}

const baseName = (item) => toText(
  item?.nome ?? item?.name ?? item?.item ?? item?.label ?? item?.title ?? item?.prodotto ?? item?.drink,
  ''
);

const baseDetail = (item) => toText(
  item?.dettaglio ?? item?.detail ?? item?.variant ?? item?.variante ?? item?.opzione ?? item?.option ?? item?.note,
  ''
);

const genericContainers = new Set([
  'gin', 'rum', 'vodka', 'whisky / bourbon', 'whisky/bourbon',
  'liquori', 'digestivi', 'premium', 'premium & digestivi'
]);

const ordine = rawItems.map((item, idx) => {
  const src = (item && typeof item === 'object') ? item : { nome: item, quantita: 1 };
  let rawItemName = baseName(src);
  let detailRaw = baseDetail(src);
  const variant = detailRaw.replace(/^\((.*)\)$/, '$1').trim();

  if (!rawItemName) {
    validationErrors.push(`Item at index ${idx} is missing a product name.`);
  }

  const rawQty = src.quantita ?? src.quantity ?? src.qty ?? 1;
  const parsedQty = Number(rawQty);
  if (
    rawQty === '' ||
    rawQty === null ||
    typeof rawQty === 'boolean' ||
    !Number.isFinite(parsedQty) ||
    !Number.isInteger(parsedQty) ||
    parsedQty <= 0 ||
    parsedQty > 50
  ) {
    validationErrors.push(`Invalid quantity "${rawQty}" for item "${rawItemName || '#' + idx}": must be an integer between 1 and 50.`);
  }

  const rawAlcohol = src.alcol_grammi ?? src.alcol ?? src.alcohol ?? 0;
  const parsedAlcohol = Number(rawAlcohol);
  if (!Number.isFinite(parsedAlcohol) || parsedAlcohol < 0 || parsedAlcohol > 500) {
    validationErrors.push(`Invalid alcol_grammi "${rawAlcohol}" for item "${rawItemName || '#' + idx}".`);
  }

  if (variant && rawItemName.includes(' / ')) {
    const parts = rawItemName.split('/').map(p => p.trim()).filter(Boolean);
    const left = parts[0] || rawItemName;
    const alternatives = [left.split(/\s+/).pop(), ...parts.slice(1)].filter(Boolean);
    const matched = alternatives.find(a => a.toLowerCase() === variant.toLowerCase());
    if (matched) {
      const words = left.split(/\s+/).filter(Boolean);
      rawItemName = words.length > 1 ? (words.slice(0, -1).join(' ') + ' ' + matched).trim() : matched;
      detailRaw = '';
    }
  }

  if (variant && genericContainers.has(rawItemName.toLowerCase())) {
    rawItemName = variant;
    detailRaw = '';
  }

  const cleanQty = Number.isInteger(parsedQty) && parsedQty > 0 ? parsedQty : 1;
  const cleanAlcol = Number.isFinite(parsedAlcohol) && parsedAlcohol >= 0 ? parsedAlcohol : 0;

  return {
    nome: rawItemName || 'Elemento non valido',
    dettaglio: detailRaw,
    quantita: cleanQty,
    alcol_grammi: cleanAlcol
  };
});

const speechAliases = {
  'cocacola': 'Coca Cola',
  'coca cola': 'Coca Cola',
  'redbull': 'Red Bull',
  'red bull': 'Red Bull',
  'the freddo pesca': 'Te freddo alla pesca',
  'acqua tonica': 'acqua tonica',
  'birra bionda': 'birra bionda',
  'aperol spritz': 'Aperol Spritz',
  'campari spritz': 'Campari Spritz',
  'limoncello spritz': 'Limoncello Spritz',
  'il venturo spritz': 'Venturo Spritz',
  'summer spritz': 'Spritz estivo',
  'gin tonic': 'gin con acqua tonica',
  'gin lemon': 'gin lemon',
  'vodka tonic': 'vodka con acqua tonica',
  'vodka lemon': 'vodka lemon',
  'vodka coffee tonic': 'vodka con caffe e tonica',
