  'etsu hokkaido giappone': 'Etsu, Hokkaido Giappone',
  'ginnastic match citrus blend': 'Ginnastic Match agli agrumi',
  'cabana': 'Cabana',
  'pampero anniversario': 'Pampero Anniversario',
  'monkai': 'Monkai',
  'finland': 'Finlandia',
  'wyborowa russia': 'Wyborowa, Russia',
  'jack daniel s no 7 apple': 'Jack Daniels numero sette alla mela',
  'talisker skye single malt 10 anni': 'Talisker Sky single malt, dieci anni',
  'lagavulin 16 anni': 'Lagavulin, sedici anni',
  'glengrant': 'Glen Grant',
  'limoncello menton': 'Limoncello Menton',
  'jagermeister': 'Iegermaister',
  'grand marnier': 'Gran Marnier',
  'molinari sambuca': 'Molinari Sambuca',
  'sandeman porto': 'Sandeman Porto',
  'fernet branca': 'Fernet Branca'
};

const speechName = (name, detail = '') => {
  let label = toText(name);
  if (detail) label += ' ' + toText(detail);
  const key = normalizeKey(label);
  return speechAliases[key] || speechAliases[normalizeKey(name)] || label;
};

const articleOverrides = {
  'birra bionda': 'una', 'cocacola': 'una', 'coca cola': 'una', 'acqua tonica': 'una',
  'redbull': 'una', 'red bull': 'una', 'the freddo pesca': 'un', 'vodka': 'una',
  'finland': 'una', 'wyborowa russia': 'una', 'molinari sambuca': 'una',
  'aperol spritz': 'un', 'campari spritz': 'un', 'limoncello spritz': 'un',
  'il venturo spritz': 'un', 'summer spritz': 'un', 'prosecco': 'un',
  'gin tonic': 'un', 'gin lemon': 'un', 'vodka tonic': 'un', 'vodka lemon': 'un',
  'vodka coffee tonic': 'un', 'cuba libre': 'un', 'negroni': 'un',
  'negroni sbagliato': 'un', 'dry martini': 'un', 'watermelon gin tonic': 'un',
  'white dragon': 'un', 'jagermeister bomb': 'un', 'jagermeister deer beer': 'un',
  'jagermeister': 'un', 'limoncello menton': 'un', 'fernet branca': 'un',
  'grand marnier': 'un', 'sandeman porto': 'un', 'mg dry gin villanova spagna': 'un',
  'larios malaga spagna': 'un', 'martin miller s london uk': 'un', 'tanqueray': 'un',
  'boigin sardegna': 'un', 'sabatini toscana': 'un', 'malfy limone torino': 'un',
  'etsu hokkaido giappone': 'un', 'ginnastic match citrus blend': 'un',
  'cabana': 'un', 'pampero anniversario': 'un', 'monkai': 'un',
  'jack daniel s no 7 apple': 'un', 'talisker skye single malt 10 anni': 'un',
  'lagavulin 16 anni': 'un', 'glengrant': 'un'
};

const articleFor = (name, detail = '') => {
  const combined = normalizeKey((name || '') + ' ' + (detail || ''));
  const exact = articleOverrides[combined] || articleOverrides[normalizeKey(name)];
  if (exact) return exact;
  const spoken = normalizeKey(speechName(name, detail));
  if (articleOverrides[spoken]) return articleOverrides[spoken];
  if (/^(aperol|campari|gin|vodka|negroni|martini|prosecco|limoncello|jager|ieger|fernet|grand|talisker|lagavulin|jack|rum|whisky|dry|white|watermelon|cuba)/.test(normalizeKey(name))) return 'un';
  return 'una';
};

const qtyToSpeech = (q, itemName, detail) => {
  const n = Number(q || 1);
  if (n === 1) return articleFor(itemName, detail);
  const words = { 2: 'due', 3: 'tre', 4: 'quattro', 5: 'cinque', 6: 'sei', 7: 'sette', 8: 'otto', 9: 'nove', 10: 'dieci' };
  return words[n] || String(n);
};

const alcolOrdine = Math.round(
  ordine.reduce((s, i) => s + (Number(i.alcol_grammi) || 0) * (Number(i.quantita) || 1), 0) * 10
) / 10;

const ordine_str = ordine
  .map(i => {
    let s = i.quantita + 'x ' + i.nome;
    if (i.dettaglio) s += ' ' + i.dettaglio;
    return s;
  })
  .join(', ');

const items_json = JSON.stringify(ordine);

const ordine_voce = ordine
  .map(i => {
    const detail = i.dettaglio || '';
    return qtyToSpeech(i.quantita, i.nome, detail) + ' ' + speechName(i.nome, detail);
  })
  .join(', ');

const messaggio_voce = 'Nuovo ordine da ' + nome + '. ' + ordine_voce + '.';
const sanitized_voce = String(messaggio_voce)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^A-Za-z0-9 .,:;!?()'\-/]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    isValid: validationErrors.length === 0,
    validationErrors,
    orderId,
    claimSid,
    ttsIdempotencyKey,
    customerId,
    nome,
    pesoKg,
    widmarkR,
    orario,
    today,
    ordine,
    items_json,
    ordine_str,
    ordine_voce,
    messaggio_voce,
    sanitized_voce,
    alcolOrdine
  }
}];

// A staticData object is NOT a cross-worker atomic mutex. Use a unique claim token and verify persisted rows.
// IMPORTANT: DataTables without a unique SID constraint cannot guarantee exactly-once under concurrent execution.
const order=$input.first().json;
const claimToken=String($execution.id)+':'+Date.now()+':'+Math.random().toString(36).slice(2);
return [{json:{...order,claimToken,inMemoryDuplicate:false,claimTimestamp:new Date().toISOString()}}];

// First-Writer-Wins verification on DataTable rows + P1 DataTable output validation
const rawItems = $input.all().map(i => i.json);
const lockInfo = $('Acquire Atomic Lock & Token').first().json;
const claimInsertItem = $('Claim Order ID').first()?.json || {};

const hasError = rawItems.some(r => r && r.error) || Boolean(claimInsertItem.error);
const rows = rawItems.filter(r => r && !r.error && r.sid === lockInfo.claimSid);

if (hasError || rows.length === 0) {
  return [{
    json: {
      ...lockInfo,
      isAtomicWinner: false,
      storageFailed: true,
      loserRowId: null,
      loserClaimToken: null
    }
  }];
}

const sorted = [...rows].sort((a, b) => {
  if (a.id !== undefined && b.id !== undefined && a.id !== b.id) {
    return Number(a.id) - Number(b.id);
  }
  return String(a.updated_at || '').localeCompare(String(b.updated_at || ''));
});

const winnerRow = sorted[0];
const isAtomicWinner = !lockInfo.inMemoryDuplicate && winnerRow.claim_token === lockInfo.claimToken;
const myRedundantRow = !isAtomicWinner
  ? sorted.slice(1).find(r => r.claim_token === lockInfo.claimToken)
  : null;

return [{
  json: {
    ...lockInfo,
    isAtomicWinner,
    storageFailed: false,
    winnerRowId: winnerRow.id ?? null,
    winnerState: winnerRow.state || 'pending',
    loserRowId: myRedundantRow?.id ?? null,
    loserClaimToken: myRedundantRow ? lockInfo.claimToken : null
  }
}];

