// P1 Fix: Time-adjusted Widmark BAC estimation (accounts for bioavailability 0.80 and hepatic elimination 0.15 g/L/h)
const rawItems = $input.all().map(i => i.json);
const order = $('Acquire Atomic Lock & Token').first().json;
const { nome, customerId, orario, ordine_str, alcolOrdine, today, orderId, pesoKg = 70, widmarkR = 0.68 } = order;

const rows = rawItems.filter(r => r && !r.error && (r.item || r.alcol_grammi !== undefined));
const effectiveRows = rows.length > 0 ? rows : [{ item: ordine_str, alcol_grammi: alcolOrdine, orario, customer_id: customerId, person: nome, order_id: orderId }];

const parseHourMin = (timeStr) => {
  const m = String(timeStr || '').match(/(\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (!m) return null;
  return Number(m[1]) * 60 + Number(m[2]) + (Number(m[3] || 0) / 60);
};

const nowMinutes = parseHourMin(orario);
// Only compare clock times for same-day records; this remains an approximation, not a safety measurement.
const ABSORPTION_FACTOR = 0.80; // gastro-intestinal bioavailability
const BETA_G_L_PER_HOUR = 0.15; // standard Widmark elimination rate (g/L per hour)
const distributionVolume = pesoKg * widmarkR;

let totalAlcol = 0;
let firstDrinkMinutes = null;

for (const r of effectiveRows) {
  const grams = Number(r.alcol_grammi) || 0;
  totalAlcol += grams;
  if (grams > 0) {
    const tMin = parseHourMin(r.orario);
    if (tMin !== null && (firstDrinkMinutes === null || tMin < firstDrinkMinutes)) {
      firstDrinkMinutes = tMin;
    }
  }
}

totalAlcol = Math.round(totalAlcol * 10) / 10;
const nOrdini = effectiveRows.length;

const elapsedHours = (firstDrinkMinutes !== null && nowMinutes !== null && nowMinutes > firstDrinkMinutes)
  ? (nowMinutes - firstDrinkMinutes) / 60
  : 0;

// Gross theoretical peak (un-metabolized) vs Time-adjusted active BAC estimate
const bacLordo = totalAlcol > 0 ? (totalAlcol * ABSORPTION_FACTOR) / distributionVolume : 0;
const bacAttivo = totalAlcol > 0 ? Math.max(0, bacLordo - (BETA_G_L_PER_HOUR * elapsedHours)) : 0;
const bacStr = bacAttivo.toFixed(2);
const bacLordoStr = bacLordo.toFixed(2);

const E_OK    = String.fromCodePoint(0x1F7E2);
const E_WARN  = String.fromCodePoint(0x1F7E1);
const E_OVER  = String.fromCodePoint(0x1F534);
const E_NONE  = String.fromCodePoint(0x2B1C);
const E_LIST  = String.fromCodePoint(0x1F4CB);
const E_CLOCK = String.fromCodePoint(0x1F552);
const E_DRINK = String.fromCodePoint(0x1F378);
const E_WATER = String.fromCodePoint(0x1F964);
const E_TIME  = String.fromCodePoint(0x1F550);

let bacLevel;
if      (bacAttivo === 0) bacLevel = E_NONE;
else if (bacAttivo < 0.2) bacLevel = E_OK;
else if (bacAttivo < 0.5) bacLevel = E_WARN;
else                      bacLevel = E_OVER;

const prevOrders = effectiveRows.filter(r => r.order_id !== orderId);
const storStr = prevOrders.length > 0
  ? '\n' + E_LIST + ' Gia ordinato oggi (' + prevOrders.length + ' ordini):\n'
    + prevOrders.map(r => '  - ' + r.item + '  ' + E_CLOCK + ' ' + r.orario).join('\n')
  : '';

const bacRow = totalAlcol > 0
  ? '\n' + E_DRINK + ' Stima BAC attivo ~' + bacStr + ' g/L ' + bacLevel + ' (picco lordo ' + bacLordoStr + ' g/L | ' + totalAlcol + 'g alcol, stima indicativa Widmark)'
  : '\n' + E_WATER + ' nessun alcolico';

const messaggio = nome + ' [' + customerId + ']: ' + ordine_str
  + '\n' + E_TIME + ' ' + orario
  + storStr
  + bacRow;

return [{
  json: {
    orderId,
    customerId,
    nome,
    orario,
    ordine_str,
    messaggio,
    bac: bacStr,
    bacLordo: bacLordoStr,
    bacLevel,
    totalAlcol,
    alcolOrdine,
    nOrdini,
    today,
    historyOk: true,
    historyState: 'history_saved',
    historyError: null
  }
}];

// Build a fallback ntfy message when History DataTable fails so ntfy still delivers the order
const order = $('Acquire Atomic Lock & Token').first().json;
const errDetail = $input.first()?.json?.error?.message || $input.first()?.json?.message || 'History DataTable unavailable';
const { nome, customerId, orario, ordine_str, alcolOrdine, today, orderId, pesoKg = 70, widmarkR = 0.68 } = order;

const bacSingle = alcolOrdine > 0 ? ((alcolOrdine * 0.80) / (pesoKg * widmarkR)).toFixed(2) : '0.00';
const messaggio = nome + ' [' + customerId + ']: ' + ordine_str
  + '\n🕐 ' + orario
  + '\n⚠️ Storico giornaliero non disponibile (history_failed)'
  + (alcolOrdine > 0 ? ('\n🍸 Stima BAC singolo ordine ~' + bacSingle + ' g/L (stima indicativa)') : '\n🥤 nessun alcolico');

return [{
  json: {
    orderId,
    customerId,
    nome,
    orario,
    ordine_str,
    messaggio,
    bac: bacSingle,
    bacLevel: '⚠️',
    totalAlcol: alcolOrdine,
    alcolOrdine,
    nOrdini: 1,
    today,
    historyOk: false,
    historyState: 'history_failed',
    historyError: String(errDetail)
  }
}];

const prev = $('Calculate Cumulative BAC1').isExecuted
  ? $('Calculate Cumulative BAC1').first().json
  : $('Build Fallback Message (History Failed)1').first().json;

return [{
  json: {
    branch: 'ntfy_and_history',
    orderId: prev.orderId,
    customerId: prev.customerId,
    historyOk: prev.historyOk,
    historyState: prev.historyState,
    historyError: prev.historyError,
    ntfyOk: true,
    ntfyState: 'completed',
    ntfyError: null,
    messaggio: prev.messaggio,
    bac: prev.bac,
    totalAlcol: prev.totalAlcol
  }
}];

const prev = $('Calculate Cumulative BAC1').isExecuted
  ? $('Calculate Cumulative BAC1').first().json
  : $('Build Fallback Message (History Failed)1').first().json;
const errObj = $input.first()?.json || {};
const errMsg = errObj.error?.message || errObj.message || 'ntfy request failed';

return [{
  json: {
    branch: 'ntfy_and_history',
    orderId: prev.orderId,
    customerId: prev.customerId,
    historyOk: prev.historyOk,
    historyState: prev.historyState,
    historyError: prev.historyError,
    ntfyOk: false,
    ntfyState: 'ntfy_failed',
    ntfyError: String(errMsg),
    messaggio: prev.messaggio,
    bac: prev.bac,
    totalAlcol: prev.totalAlcol
  }
}];

const order = $('Acquire Atomic Lock & Token').first().json;
return [{
  json: {
    ttsBranch: 'tts',
    ttsOrderId: order.orderId,
    ttsCustomerId: order.customerId,
    ttsIdempotencyKey: order.ttsIdempotencyKey,
    ttsOk: true,
    ttsUncertain: false,
    ttsState: 'completed',
    ttsError: null,
    messaggio_voce: order.messaggio_voce
  }
}];

// Distinguish definite failure (connection refused / 4xx / 5xx) from uncertain timeout after dispatch
const order = $('Acquire Atomic Lock & Token').first().json;
const errItem = $input.first()?.json || {};
const rawMsg = String(errItem.error?.message || errItem.message || 'TTS request failed');
const rawCode = String(errItem.error?.code || errItem.code || '');
const statusCode = Number(errItem.statusCode || errItem.error?.statusCode || 0);

const isDefiniteRefusal = /econnrefused|ehostunreach|enetunreach|enotfound/i.test(rawMsg + ' ' + rawCode) || statusCode >= 400;
const isTimeoutOrUncertain = !isDefiniteRefusal && (
  /timeout|timed out|etimedout|esockettimedout|econnaborted|socket hang up|econnreset/i.test(rawMsg + ' ' + rawCode) ||
  statusCode === 0
);

return [{
  json: {
    ttsBranch: 'tts',
    ttsOrderId: order.orderId,
    ttsCustomerId: order.customerId,
    ttsIdempotencyKey: order.ttsIdempotencyKey,
    ttsOk: false,
    ttsUncertain: isTimeoutOrUncertain,
    ttsState: isTimeoutOrUncertain ? 'tts_uncertain' : 'needs_review',
    ttsError: rawMsg,
    doNotAutoReplayTts: isTimeoutOrUncertain,
    messaggio_voce: order.messaggio_voce
  }
}];

// Consolidate Results from both merged branches (combineByPosition merges TTS + ntfy/history fields into a single item)
const allItems = $input.all().map(i => i.json);
const merged = Object.assign({}, ...allItems);
const order = $('Acquire Atomic Lock & Token').first().json;

const historyOk = merged.historyOk === true;
const ntfyOk = merged.ntfyOk === true;
const ttsOk = merged.ttsOk === true;
const ttsUncertain = merged.ttsUncertain === true;

const failedServices = [];
if (!historyOk) failedServices.push(`History (${merged.historyError || 'failed'})`);
if (!ntfyOk) failedServices.push(`ntfy (${merged.ntfyError || 'failed'})`);
if (!ttsOk) {
  failedServices.push(
    ttsUncertain
      ? `TTS Uncertain/Timeout (${merged.ttsError || 'timeout - do not auto-replay'})`
      : `TTS Definite Failure (${merged.ttsError || 'error'})`
  );
}

const issueCount = (!historyOk ? 1 : 0) + (!ntfyOk ? 1 : 0) + (!ttsOk ? 1 : 0);

let finalState = 'completed';
if (issueCount === 0) {
  finalState = 'completed';
} else if (issueCount > 1) {
  finalState = 'needs_review';
} else if (!historyOk) {
  finalState = 'history_failed';
} else if (!ntfyOk) {
  finalState = 'ntfy_failed';
} else if (ttsUncertain) {
  finalState = 'tts_uncertain';
} else {
  finalState = 'needs_review';
}

const errorSummary = failedServices.join(' | ');
const messaggio = merged.messaggio || (order.nome + ': ' + order.ordine_str);

const fallbackAlertText = [
  `🚨 *Menu Order Alert — State: ${finalState.toUpperCase()}*`,
  `• *Order ID*: ${order.orderId}`,
  `• *Customer*: ${order.nome} (${order.customerId})`,
  `• *Time*: ${order.orario}`,
  `• *Failed Services*: ${errorSummary || 'None'}`,
  ttsUncertain ? `⚠️ *TTS Note*: Timeout after dispatch (tts_uncertain, Idempotency-Key: ${order.ttsIdempotencyKey}). Do NOT replay automatically to avoid duplicate voice announcement.` : '',
  '',
  `📋 *Original Order Message*:`,
  messaggio,
  '',
  `🔊 *Original Voice Text*:`,
  order.messaggio_voce
].filter(Boolean).join('\n');

const escapeHtml = (s) => String(s || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const fallbackAlertHtml = `
<div style="font-family: sans-serif; line-height: 1.5; color: #1f2937;">
  <h2 style="color: #b91c1c;">🚨 Menu Order Alert — State: ${escapeHtml(finalState.toUpperCase())}</h2>
  <ul>
    <li><strong>Order ID:</strong> <code>${escapeHtml(order.orderId)}</code></li>
    <li><strong>Claim SID:</strong> <code>${escapeHtml(order.claimSid)}</code></li>
    <li><strong>Customer:</strong> ${escapeHtml(order.nome)} (<code>${escapeHtml(order.customerId)}</code>)</li>
    <li><strong>Time:</strong> ${escapeHtml(order.orario)}</li>
    <li><strong>History Status:</strong> ${historyOk ? 'OK' : 'FAILED (' + escapeHtml(merged.historyError) + ')'}</li>
    <li><strong>ntfy Status:</strong> ${ntfyOk ? 'OK' : 'FAILED (' + escapeHtml(merged.ntfyError) + ')'}</li>
    <li><strong>TTS Status:</strong> ${ttsOk ? 'OK' : (ttsUncertain ? 'UNCERTAIN / TIMEOUT (' + escapeHtml(merged.ttsError) + ')' : 'FAILED (' + escapeHtml(merged.ttsError) + ')')}</li>
    <li><strong>TTS Idempotency Key:</strong> <code>${escapeHtml(order.ttsIdempotencyKey)}</code></li>
  </ul>
  ${ttsUncertain ? '<p style="color: #92400e; background: #fef3c7; padding: 8px 12px; border-radius: 4px;"><strong>⚠️ TTS Note:</strong> Timeout after dispatch (<code>tts_uncertain</code>). Do NOT replay automatically without verifying whether the announcement already played.</p>' : ''}
  <h3>📋 Original Order Message</h3>
  <pre style="background: #f3f4f6; padding: 12px; border-radius: 4px;">${escapeHtml(messaggio)}</pre>
  <h3>🔊 Original Voice Text</h3>
  <pre style="background: #f3f4f6; padding: 12px; border-radius: 4px;">${escapeHtml(order.messaggio_voce)}</pre>
</div>`.trim();

return [{
  json: {
    orderId: order.orderId,
    claimSid: order.claimSid,
    customerId: order.customerId,
    nome: order.nome,
    orario: order.orario,
    today: order.today,
    ordine_str: order.ordine_str,
    messaggio,
    messaggio_voce: order.messaggio_voce,
    finalState,
    needsFallback: finalState !== 'completed',
    historyOk,
    ntfyOk,
    ttsOk,
    ttsUncertain,
    failedServices,
    errorSummary,
    fallbackAlertText,
    fallbackAlertHtml
  }
}];

// Compute yesterday's date in Europe/Rome timezone
const now = new Date();
const romeNowStr = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Rome' }).format(now);
const [y, m, d] = romeNowStr.split('-').map(Number);
const yesterdayUtc = new Date(Date.UTC(y, m - 1, d - 1, 12, 0, 0));
const yesterday = yesterdayUtc.toISOString().slice(0, 10);
const yesterdayDisplay = `${String(yesterdayUtc.getUTCDate()).padStart(2, '0')}/${String(yesterdayUtc.getUTCMonth() + 1).padStart(2, '0')}/${yesterdayUtc.getUTCFullYear()}`;

return [{ json: { yesterday, yesterdayDisplay } }];

// P2 Fix: Build complete daily summary report using structured items_json (with fallback to item string for legacy records)
const { yesterday, yesterdayDisplay } = $('Prepare Yesterday Filter1').first().json;
const rawItems = $input.all().map(i => i.json);
if (rawItems.some(r => r && r.error)) throw new Error('Daily report DataTable read failed: cannot report zero orders');
const rows = rawItems.filter(r => r && !r.error && (r.items_json || r.item));

if (rows.length === 0) {
  return [{
    json: {
      yesterday,
      totalOrders: 0,
      reportMessage: `📊 Report Giornaliero Menu (${yesterdayDisplay})\nNessun ordine registrato nella giornata di ieri.`
    }
  }];
}

const productCounts = new Map();
const customerStats = new Map();
let totalDrinks = 0;
let totalAlcolGrams = 0;

for (const row of rows) {
  const custKey = row.customer_id || row.person || 'anonimo';
  const custName = row.person || custKey;
  const rowAlcol = Number(row.alcol_grammi) || 0;
  totalAlcolGrams += rowAlcol;

  if (!customerStats.has(custKey)) {
    customerStats.set(custKey, { customerId: custKey, nome: custName, orders: 0, drinks: 0, alcol: 0 });
  }
  const cStat = customerStats.get(custKey);
  cStat.orders += 1;
  cStat.alcol = Math.round((cStat.alcol + rowAlcol) * 10) / 10;

  let parsedItems = null;
  if (row.items_json && typeof row.items_json === 'string') {
    try {
      const candidate = JSON.parse(row.items_json);
      if (Array.isArray(candidate)) parsedItems = candidate;
    } catch (_) {
      parsedItems = null;
    }
  }

  if (parsedItems && parsedItems.length > 0) {
    for (const it of parsedItems) {
      const qty = Number(it.quantita) || 1;
      const label = [it.nome, it.dettaglio].filter(Boolean).join(' ').trim() || 'Prodotto';
      totalDrinks += qty;
      cStat.drinks += qty;
      productCounts.set(label, (productCounts.get(label) || 0) + qty);
    }
  } else {
    const parts = String(row.item || '').split(',').map(s => s.trim()).filter(Boolean);
    for (const part of parts) {
      const m = part.match(/^(\d+)x\s+(.+)$/i);
      const qty = m ? Number(m[1]) : 1;
      const prodName = m ? m[2].trim() : part;
      totalDrinks += qty;
      cStat.drinks += qty;
      productCounts.set(prodName, (productCounts.get(prodName) || 0) + qty);
    }
  }
}

const topProducts = [...productCounts.entries()]
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([name, count], idx) => `  ${idx + 1}. ${name}: ${count}x`)
  .join('\n');

const customerList = [...customerStats.values()]
  .sort((a, b) => b.alcol - a.alcol || b.drinks - a.drinks)
  .map(c => {
    const bacLordo = c.alcol > 0 ? ((c.alcol * 0.80) / (70 * 0.68)).toFixed(2) : '0.00';
    return `  - ${c.nome} [${c.customerId}]: ${c.orders} ordini (${c.drinks} prod.) | ${c.alcol.toFixed(1)}g alcol (picco lordo ~${bacLordo} g/L)`;
  })
  .join('\n');

const maxCustomerAlcol = Math.max(...[...customerStats.values()].map(c => c.alcol), 0);
const maxBac = maxCustomerAlcol > 0 ? ((maxCustomerAlcol * 0.80) / (70 * 0.68)).toFixed(2) : '0.00';
const avgBac = customerStats.size > 0
  ? (((totalAlcolGrams / customerStats.size) * 0.80) / (70 * 0.68)).toFixed(2)
  : '0.00';

const reportMessage = [
  `📊 Report Giornaliero Menu — ${yesterdayDisplay}`,
  `🧾 Ordini totali: ${rows.length} (${totalDrinks} consumazioni)`,
  `👥 Clienti attivi: ${customerStats.size}`,
  `🍸 Alcol totale erogato: ${totalAlcolGrams.toFixed(1)} g (picco lordo medio ~${avgBac} g/L | max ~${maxBac} g/L)`,
  '',
  `🏆 Prodotti più richiesti:`,
  topProducts,
  '',
  `👤 Dettaglio clienti:`,
  customerList
].join('\n');

return [{
  json: {
    yesterday,
    yesterdayDisplay,
    totalOrders: rows.length,
    totalDrinks,
    activeCustomers: customerStats.size,
    totalAlcolGrams: Math.round(totalAlcolGrams * 10) / 10,
    avgBac,
    maxBac,
    reportMessage
  }
}];

// P2 Fix: Unified retention policy (default 30 days) aligned across both Order History and Completed Claims
const retentionDays = Math.max(7, Number($vars.MENU_RETENTION_DAYS || $vars.MENU_HISTORY_RETENTION_DAYS || 30));

const now = new Date();
const cutoffTimeMs = now.getTime() - retentionDays * 86400000;
const historyCutoff = new Date(cutoffTimeMs).toISOString().slice(0, 10);
const claimsCutoffIso = new Date(cutoffTimeMs).toISOString();

return [{
  json: {
    retentionDays,
    historyRetentionDays: retentionDays,
    completedClaimsRetentionDays: retentionDays,
    historyCutoff,
    claimsCutoffIso,
    protectedStates: ['pending', 'history_saved', 'history_failed', 'ntfy_failed', 'tts_uncertain', 'needs_review']
  }
}];

// Filter only 'completed' claims older than claimsCutoffIso. Never delete recovery/review or recent claims.
const { claimsCutoffIso } = $('Maintenance Retention Config1').first().json;
const expiredClaims = $input.all()
  .map(i => i.json)
  .filter(r =>
    r &&
    !r.error &&
    r.id !== undefined &&
    r.sid &&
    r.state === 'completed' &&
    r.updated_at &&
    String(r.updated_at) < String(claimsCutoffIso)
  );

return expiredClaims.map(r => ({
  json: {
    id: r.id,
    sid: r.sid,
    state: 'completed',
    updated_at: r.updated_at
  }
}));

const { historyCutoff } = $('Maintenance Retention Config1').first().json;
const expiredRows = $input.all()
  .map(i => i.json)
  .filter(r =>
    r &&
    !r.error &&
    r.id !== undefined &&
    r.order_id &&
    r.data &&
    String(r.data) < String(historyCutoff)
  );

return expiredRows.map(r => ({
  json: {
    id: r.id,
    order_id: r.order_id,
    data: r.data
  }
}));

// P1 Fix: Portable blueprint for creating/verifying each required DataTable individually
return [
  {
    json: {
      initMarker: '__schema_init__',
      apiBaseUrl: ($vars.N8N_INTERNAL_URL || 'http://127.0.0.1:5678').replace(/\/$/, ''),
      requiredTables: [
        {
          name: 'menu paoloronco intranet',
          columns: [
            { name: 'order_id', type: 'string' },
            { name: 'customer_id', type: 'string' },
            { name: 'person', type: 'string' },
            { name: 'item', type: 'string' },
            { name: 'items_json', type: 'string' },
            { name: 'alcol_grammi', type: 'number' },
            { name: 'data', type: 'string' },
            { name: 'orario', type: 'string' }
          ]
        },
        {
          name: 'Notification SID Claims',
          columns: [
            { name: 'sid', type: 'string' },
            { name: 'claim_token', type: 'string' },
            { name: 'order_id', type: 'string' },
            { name: 'customer_id', type: 'string' },
            { name: 'workflow', type: 'string' },
            { name: 'channel', type: 'string' },
            { name: 'state', type: 'string' },
            { name: 'error_detail', type: 'string' },
            { name: 'updated_at', type: 'string' }
          ]
        }
      ]
    }
  }
];
